                # Check required fields from spec
                expected_fields = ["tag", "forecastHour", "validTime", "hazard", "geometryType", 
                                 "latlonpairs", "due_to", "receiptTime", "issueTime", "expireTime", "product"]
                
                for field in expected_fields:
                    if field in first_item:
                        # Type validation based on spec
                        if field == "tag":
                            assert isinstance(first_item[field], str)
                        elif field == "forecastHour":
                            assert isinstance(first_item[field], int)
                        elif field == "validTime":
                            assert isinstance(first_item[field], str)
                        elif field == "hazard":
                            assert isinstance(first_item[field], str)
                        elif field == "geometryType":
                            assert isinstance(first_item[field], str)
                        elif field == "latlonpairs":
                            assert isinstance(first_item[field], int)
                        elif field == "due_to":
                            assert isinstance(first_item[field], str)
                        elif field in ["receiptTime", "issueTime", "expireTime"]:
                            assert isinstance(first_item[field], int)
                        elif field == "product":
                            assert isinstance(first_item[field], str)
                
                # Check coordinates structure if present
                if "coords" in first_item and first_item["coords"]:
                    coord_item = first_item["coords"][0]
                    assert "lat" in coord_item
                    assert "lon" in coord_item
