    def test_gairmet_concurrent_requests(self, api_client):
        """Test multiple concurrent requests to gairmet endpoint"""
        import concurrent.futures
        
        def make_request():
            return api_client.get("/api/data/gairmet")
        
        with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
            futures = [executor.submit(make_request) for _ in range(5)]
            results = [future.result() for future in concurrent.futures.as_completed(futures)]
        
        for response in results:
            assert response.status_code in [200, 400, 429]  # 429 for rate limiting
    
